      const card = btn.closest('.card');
      card.querySelector('.eps').innerHTML = episodes.map(ep=>'<button class="episode" data-id="'+escapeHtml(ep.Key || '')+'" data-url="'+escapeHtml(ep.Url || '')+'">'+escapeHtml(ep.Name)+'</button>').join('');
      card.querySelectorAll('.episode').forEach(item => item.onclick=async()=>push(item.dataset.id, item.dataset.url));
