    function renderEmby() {
      providerMessage('emby');
      const list = embyList();
      if (editingEmbyIndex >= list.length) editingEmbyIndex = -1;
      const editing = editingEmbyIndex >= 0 ? list[editingEmbyIndex] : { servername:'', serverurl:'', username:'', password:'' };
      const options = list.length ? list.map((item, index) => '<option value="' + index + '" ' + (index === (editingEmbyIndex >= 0 ? editingEmbyIndex : embyChooseIndex()) ? 'selected' : '') + '>' + (index + 1) + '. ' + escapeHtml(item.servername || ('Emby ' + (index + 1))) + (item.choose === 1 ? '\uFF08\u9ED8\u8BA4\uFF09' : '') + '</option>').join('') : '<option value="-1">\u6682\u65E0\u670D\u52A1\u5668</option>';
      $('detailBody').innerHTML =
        '<div class="status">\u6B63\u5728\u7F16\u8F91\uFF1A' + escapeHtml(editing.servername || '\u65B0\u589E\u670D\u52A1\u5668') + '</div>' +
        '<div><label for="embySelect">\u670D\u52A1\u5668</label><select id="embySelect">' + options + '</select></div>' +
        input('embyName','\u670D\u52A1\u5668\u540D\u79F0',editing.servername) +
        input('embyUrl','\u670D\u52A1\u5668\u5730\u5740',editing.serverurl) +
        input('embyUser','\u7528\u6237\u540D',editing.username) +
        input('embyPass','\u5BC6\u7801',editing.password) +
        actions([['saveEmby','\u4FDD\u5B58\u670D\u52A1\u5668','primary'],['chooseEmbyEdit','\u8BBE\u4E3A\u9ED8\u8BA4','secondary'],['testEmbyEdit','\u6D4B\u8BD5\u767B\u5F55','ghost'],['newEmby','\u65B0\u589E\u670D\u52A1\u5668','primary'],['deleteEmbyEdit','\u5220\u9664\u670D\u52A1\u5668','danger']]) +
        '<div class="hint">EmbyDiy \u901A\u8FC7 ext \u91CC\u7684 embynumber \u8BFB\u53D6\u8FD9\u91CC\u7684\u670D\u52A1\u5668\u5E8F\u53F7\u3002</div>';
      $('embySelect').onchange = () => {
        editingEmbyIndex = Number($('embySelect').value);
        renderEmby();
      };
      $('newEmby').onclick = () => { editingEmbyIndex = -1; renderEmby(); };
      $('saveEmby').onclick = saveEmby;
      $('chooseEmbyEdit').onclick = () => chooseEmby(editingEmbyIndex >= 0 ? editingEmbyIndex : embyChooseIndex()).catch(handleError);
      $('testEmbyEdit').onclick = testEmbyEdit;
      $('deleteEmbyEdit').onclick = () => deleteEmby(editingEmbyIndex >= 0 ? editingEmbyIndex : embyChooseIndex()).catch(handleError);
    }

